// Runs the exact Buzzer_Driver class extracted from Core/Inc/hw_sensors.h.
// The real GlobalStore, SysAudio and preference/session headers are used; only
// the timer registers and HAL tick are fake, so ownership/priority/rate/lease
// behaviour is checked on the production driver update path.

#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "game_tone_driver_fakes.h"

#include "buzzer_driver_staged.hpp" // exact production class, generated by the test

static int failures;
#define CHECK(x) do { if (!(x)) { fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #x); ++failures; } } while (0)

GlobalDataStore GlobalStore = {};
std::atomic<Crabit::AmebaPhase> Crabit::ameba_phase(Crabit::AmebaPhase::Inactive);
volatile bool g_coproc_active = false;
TIM_HandleTypeDef htim15 = {};

static FakeTimInstance fake_instance = {};
static uint32_t fake_now = 0;
static uint32_t fake_compare = 0;
static uint32_t fake_autoreload = 0;
static uint32_t fake_prescaler = 0;
static int fake_pwm_starts = 0;
static int fake_tone_starts = 0;

uint32_t HAL_GetTick(void) { return fake_now; }
void fakeTimSetPrescaler(uint32_t value) { fake_prescaler = value; }
void fakeTimSetCompare(uint32_t value) {
    fake_compare = value;
    if (value != 0) ++fake_tone_starts;
}
void fakeTimSetAutoReload(uint32_t value) { fake_autoreload = value; }
void fakePwmStart(void) { ++fake_pwm_starts; }

struct BuzzerProbe { bool is_active; };

static bool audible(Buzzer_Driver& driver) {
    return reinterpret_cast<const BuzzerProbe*>(driver.getData())->is_active;
}

static bool post(const char* text, uint32_t now) {
    const bool session = Crabit::amebaSessionActive() || g_coproc_active;
    return CrabitTone::handleFrame(text, strlen(text), 0, session, now);
}

static void resetAll(Buzzer_Driver& driver) {
    CrabitTone::reset();
    GlobalStore = GlobalDataStore{};
    GlobalStore.sys_volume = 100;
    CrabitPreferences::current = CrabitPreferences::Record{};
    Crabit::setAmebaPhase(Crabit::AmebaPhase::Running);
    g_coproc_active = false;
    fake_now = 0;
    fake_compare = 0;
    fake_autoreload = 0;
    fake_prescaler = 0;
    fake_pwm_starts = 0;
    fake_tone_starts = 0;
    fake_instance.EGR = 0;
    htim15.Instance = &fake_instance;
    driver.init();
    fake_compare = 0; // init silence is not a tone start
    fake_tone_starts = 0;
}

static void testUserFeedbackPath() {
    Buzzer_Driver driver;
    resetAll(driver);
    CHECK(fake_pwm_starts == 1);
    CHECK(fake_prescaler == 79);

    SysAudio::play(2500, 10);
    driver.update();
    CHECK(fake_compare > 0 && audible(driver));
    CHECK(fake_autoreload == 1000000u / 2500u);

    fake_now = 9;
    driver.update();
    CHECK(fake_compare > 0 && audible(driver));
    fake_now = 10;
    driver.update();
    CHECK(fake_compare == 0 && !audible(driver));

    // Existing low-frequency clamp is preserved.
    SysAudio::play(50, 10);
    driver.update();
    CHECK(fake_autoreload == 10000); // 1 MHz / 100 Hz
}

static void testGameCueAndStop() {
    Buzzer_Driver driver;
    resetAll(driver);
    fake_now = 1000;

    CHECK(post("440,30", fake_now));
    driver.update();
    CHECK(fake_compare > 0 && audible(driver));
    CHECK(fake_autoreload == 1000000u / 440u);

    fake_now += 10;
    driver.update();
    CHECK(fake_compare > 0 && audible(driver)); // one shot, still sounding
    CHECK(fake_tone_starts == 1);

    CHECK(post("0,0", fake_now));
    driver.update();
    CHECK(fake_compare == 0 && !audible(driver));
    CHECK(post("0,0", fake_now));
    driver.update();
    CHECK(fake_compare == 0 && fake_tone_starts == 1); // no-op stop
}

static void testUserPriorityAndGameOwnership() {
    Buzzer_Driver driver;
    resetAll(driver);
    fake_now = 2000;

    CHECK(post("440,100", fake_now));
    driver.update();
    CHECK(fake_compare > 0 && audible(driver));

    // User feedback preempts the game tone on the same driver path.
    SysAudio::play(2500, 30);
    driver.update();
    CHECK(fake_compare > 0 && audible(driver));
    CHECK(fake_autoreload == 1000000u / 2500u);

    // A game cue during user feedback is dropped, not replayed later.
    CHECK(post("880,20", fake_now));
    driver.update();
    CHECK(audible(driver));
    const int user_starts = fake_tone_starts;
    fake_now += 30;
    driver.update();
    CHECK(fake_compare == 0 && !audible(driver));
    CHECK(fake_tone_starts == user_starts);

    // A stop during user feedback must not silence the user tone.
    SysAudio::play(2500, 50);
    driver.update();
    CHECK(fake_compare > 0);
    CHECK(post("0,0", fake_now));
    driver.update();
    CHECK(fake_compare > 0 && audible(driver));
    fake_now += 50;
    driver.update();
    CHECK(fake_compare == 0 && !audible(driver));

    // After user feedback ends, a new game cue is allowed again.
    CHECK(post("660,20", fake_now));
    driver.update();
    CHECK(fake_compare > 0 && audible(driver));
}

static void testMuteVolumeAndSession() {
    Buzzer_Driver driver;
    resetAll(driver);
    fake_now = 3000;

    CHECK(post("440,100", fake_now));
    driver.update();
    CHECK(fake_compare > 0 && audible(driver));

    CrabitPreferences::Record flags = CrabitPreferences::Record{};
    flags.flags &= static_cast<uint8_t>(~CrabitPreferences::Sound);
    CrabitPreferences::current = flags;
    fake_now += 10;
    driver.update();
    CHECK(fake_compare == 0 && !audible(driver)); // mute cancels active game tone

    // Mute discards a pending cue too.
    CHECK(post("550,20", fake_now));
    driver.update();
    CrabitPreferences::current = CrabitPreferences::Record{};
    fake_now += 10;
    driver.update();
    CHECK(fake_compare == 0 && !audible(driver));

    // Zero volume is the same gate.
    CHECK(post("550,20", fake_now));
    GlobalStore.sys_volume = 0;
    driver.update();
    GlobalStore.sys_volume = 100;
    fake_now += 10;
    driver.update();
    CHECK(fake_compare == 0 && !audible(driver));

    // Session loss cancels active and pending game tones.
    CHECK(post("700,40", fake_now));
    driver.update();
    CHECK(fake_compare > 0 && audible(driver));
    Crabit::setAmebaPhase(Crabit::AmebaPhase::Inactive);
    fake_now += 10;
    driver.update();
    CHECK(fake_compare == 0 && !audible(driver));

    CHECK(!post("800,20", fake_now)); // inactive session is rejected at the UART
    driver.update();
    CHECK(fake_compare == 0 && !audible(driver));

    // The existing coproc handover flag is enough on its own.
    g_coproc_active = true;
    CHECK(post("900,20", fake_now));
    driver.update();
    CHECK(fake_compare > 0 && audible(driver));
    g_coproc_active = false;
    fake_now += 10;
    driver.update();
    CHECK(fake_compare == 0 && !audible(driver));
}

static void testRateLimitAndLease() {
    Buzzer_Driver driver;
    resetAll(driver);
    fake_now = 10000;

    for (int i = 0; i < CrabitTone::kMaxStartsPerSecond; ++i) {
        CHECK(post("440,10", fake_now));
        driver.update();
    }
    CHECK(fake_tone_starts == CrabitTone::kMaxStartsPerSecond);

    CHECK(post("550,10", fake_now)); // latest mail arrives...
    driver.update();
    CHECK(fake_tone_starts == CrabitTone::kMaxStartsPerSecond); // ...rate limit drops it

    CHECK(post("0,0", fake_now)); // stop bypasses the start budget
    driver.update();
    CHECK(fake_compare == 0 && !audible(driver));

    CHECK(post("550,10", fake_now));
    driver.update();
    CHECK(fake_compare == 0);
    fake_now += 999;
    CHECK(post("550,10", fake_now));
    driver.update();
    CHECK(fake_compare == 0);
    fake_now += 1;
    CHECK(post("550,10", fake_now));
    driver.update();
    CHECK(fake_compare > 0 && audible(driver));
    CHECK(fake_autoreload == 1000000u / 550u);

    // A 250 ms cue is never audible longer than its lease.
    Buzzer_Driver lease;
    resetAll(lease);
    fake_now = 20000;
    CHECK(post("440,250", fake_now));
    lease.update();
    CHECK(audible(lease));
    fake_now += 249;
    lease.update();
    CHECK(audible(lease));
    fake_now += 1;
    lease.update();
    CHECK(fake_compare == 0 && !audible(lease));
}

static void testTickWrap() {
    Buzzer_Driver driver;
    resetAll(driver);
    fake_now = 0xFFFFFFFFu - 100u;
    CHECK(post("440,250", fake_now));
    driver.update();
    CHECK(audible(driver));
    fake_now += 249; // crosses the wrap
    driver.update();
    CHECK(audible(driver));
    fake_now += 1;
    driver.update();
    CHECK(fake_compare == 0 && !audible(driver));

    // Rate window also resets across the wrap.
    resetAll(driver);
    fake_now = 0xFFFFFFFFu - 400u;
    for (int i = 0; i < CrabitTone::kMaxStartsPerSecond; ++i) {
        CHECK(post("440,10", fake_now));
        driver.update();
    }
    CHECK(post("440,10", fake_now));
    driver.update();
    CHECK(fake_tone_starts == CrabitTone::kMaxStartsPerSecond);
    fake_now += 1000;
    CHECK(post("440,10", fake_now));
    driver.update();
    CHECK(fake_tone_starts == CrabitTone::kMaxStartsPerSecond + 1);
}

static void testStaleMailNeverPlays() {
    Buzzer_Driver driver;
    resetAll(driver);
    fake_now = 30000;
    CHECK(post("440,10", fake_now));
    fake_now += CrabitTone::kLeaseMs + 1;
    driver.update();
    CHECK(fake_compare == 0 && !audible(driver));
    CHECK(fake_tone_starts == 0);
}

int main() {
    testUserFeedbackPath();
    testGameCueAndStop();
    testUserPriorityAndGameOwnership();
    testMuteVolumeAndSession();
    testRateLimitAndLease();
    testTickWrap();
    testStaleMailNeverPlays();
    if (failures) {
        fprintf(stderr, "%d Buzzer_Driver game-tone checks failed\n", failures);
        return 1;
    }
    puts("STM32 Buzzer_Driver game-tone checks passed");
    return 0;
}
